import{_ as s,o as a,c as e,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"存储问题排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/storage-issues.md","filePath":"zh/troubleshooting/storage-issues.md"}'),d={name:"zh/troubleshooting/storage-issues.md"};function o(i,t,l,r,c,p){return a(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="存储问题排查" tabindex="-1">存储问题排查 <a class="header-anchor" href="#存储问题排查" aria-label="Permalink to &quot;存储问题排查&quot;">​</a></h1><h2 id="有序排查" tabindex="-1">有序排查 <a class="header-anchor" href="#有序排查" aria-label="Permalink to &quot;有序排查&quot;">​</a></h2><p>运行 <code>disk-tool</code> 走一遍菜单，或使用经典拼写：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; hwinfo                 (wizard: PCI/USB pages - controller present?)</span></span>
<span class="line"><span>ush&gt; ata / ahci / nvme      (family probe output - the message names it)</span></span>
<span class="line"><span>ush&gt; dskstat                (block instances registered?)</span></span>
<span class="line"><span>ush&gt; lsblk                  (devices + partitions scanned?)</span></span>
<span class="line"><span>ush&gt; parted &lt;dev&gt;           (the partition table)</span></span>
<span class="line"><span>ush&gt; fatstat                (FAT statistics of a suspect volume)</span></span>
<span class="line"><span>ush&gt; fsck &lt;dev&gt;             (filesystem check)</span></span>
<span class="line"><span>ush&gt; fatmount &lt;dev&gt; /mnt    (mount)</span></span>
<span class="line"><span>ush&gt; fstest                 (the VFS/fs assertion suite)</span></span></code></pre></div><h2 id="经典问题" tabindex="-1">经典问题 <a class="header-anchor" href="#经典问题" aria-label="Permalink to &quot;经典问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>可能原因</th></tr></thead><tbody><tr><td>有效的 FAT32 卷被拒绝（&#39;invalid BPB&#39;）</td><td>设备节点不对，或破坏对齐的堆回归（已修复；若动过 mem_heap.c 请重跑 <code>ata_dma_test</code>）</td></tr><tr><td>重启后写入丢失</td><td>它住在 ramfs 上——只有 /etc 和已挂载的卷持久</td></tr><tr><td>U 盘出现后又消失</td><td>USB MSC 拔出路径——<code>usb_hotplug_test</code> 可复现</td></tr><tr><td>以 ext4 挂载 ext2 卷</td><td>受支持（ext2 是子集）；先查 <code>fsck</code></td></tr><tr><td>向导两次询问设备名</td><td>设计如此——mkfs/abdisk/install 路径要求重输 + 裸 y 确认</td></tr><tr><td>abdisk 之后 A/B 磁盘&quot;缺席&quot;</td><td>重跑 <code>update status</code>；向导会循环复查，直到服务看见它</td></tr></tbody></table><h2 id="破坏性路径" tabindex="-1">破坏性路径 <a class="header-anchor" href="#破坏性路径" aria-label="Permalink to &quot;破坏性路径&quot;">​</a></h2><p><code>mkfs.*</code>、<code>abdisk</code>、<code>install</code> 会毁数据。在向导中它们有防护 （重输设备名，再一个裸 <code>y</code>）；经经典/direct 分发则立即执行 ——与历史命令完全一致——脚本因此保住语义。使用经典形式 之前，对照 <code>lsblk</code> 把设备名再核对一遍。</p>`,8)])])}const b=s(d,[["render",o]]);export{u as __pageData,b as default};
